from pathlib import Path
import json
root=Path(__file__).resolve().parent
page=(root/"site_core.html").read_text(encoding="utf-8")
docs={"theory":(root/"理论与模型.html").read_text(encoding="utf-8"),"research":(root/"研究全文.html").read_text(encoding="utf-8")}
markup="""<style>#read-layer[hidden]{display:none}#read-layer{position:fixed;inset:0;z-index:1000;background:#f7f8f6}#read-layer nav{height:56px;display:flex;align-items:center;gap:10px;background:#f7f8f6;border-bottom:1px solid #dce7df;padding:8px}#read-layer button{padding:9px;background:white;border:1px solid #bbcfc1;border-radius:7px;color:#174e3c}#read-layer iframe{border:0;width:100%;height:calc(100vh - 56px)}</style><div id="read-layer" hidden role="dialog" aria-modal="true"><nav><button id="read-close">← 返回实验</button><button data-read="theory">理论与模型</button><button data-read="research">研究原文</button></nav><iframe id="read-frame" title="研究阅读页"></iframe></div>"""
data=json.dumps(docs,ensure_ascii=False).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026")
script="""<script type="application/json" id="read-data">DATA</script><script>(()=>{const docs=JSON.parse(document.getElementById('read-data').textContent),layer=document.getElementById('read-layer'),frame=document.getElementById('read-frame');function open(k){layer.hidden=false;frame.srcdoc=docs[k];document.body.style.overflow='hidden'}function close(){layer.hidden=true;frame.removeAttribute('srcdoc');document.body.style.overflow=''}document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const h=a.getAttribute('href');if(h==='理论与模型.html'||h==='研究全文.html'){e.preventDefault();open(h==='理论与模型.html'?'theory':'research')}});layer.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>open(b.dataset.read));document.getElementById('read-close').onclick=close;frame.addEventListener('load',()=>{const d=frame.contentDocument;if(!d)return;d.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const h=a.getAttribute('href');if(h==='index.html'){e.preventDefault();close()}else if(h==='理论与模型.html'||h==='研究全文.html'){e.preventDefault();open(h==='理论与模型.html'?'theory':'research')}else if(h.startsWith('#')){const el=d.getElementById(decodeURIComponent(h.slice(1)));if(el){e.preventDefault();el.scrollIntoView()}}})});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!layer.hidden)close()})})();</script>""".replace("DATA",data)
(root/"index.html").write_text(page.replace("</body>",markup+script+"</body>"),encoding="utf-8")
print("Offline index.html ready.")
